INSERT INTO instruments (instrument_id, authority_id, lg_id, kind, force, title, notes) VALUES ($q$BSC_PLANNING_SCHEME_2020$q$, $q$BSC$q$, $q$BURKE$q$, 'PLANNING_SCHEME', 'STATUTORY_INSTRUMENT', $q$Burke Shire Planning Scheme 2020$q$, $q$Citation and commencement (PDF p.2): "This planning scheme may be cited as Burke Shire Planning Scheme 2020. A notice was published in the Government Gazette No.20 on 31 January 2020 for the planning scheme for the Shire of Burke. The commencement date for the planning scheme was 7 February 2020." Council planning page (per earlier check; www host returns 403 to scripts) states the scheme was "adopted by Council at the January 2020 and has a commencement date of 7 February 2020"; no version/amendment number is published. The official PDF is served from a pre-production (OpenCities "prelive") host, burkeshire.prelive.opencities.com, which the council planning page itself links; www.burke.qld.gov.au returns 403 to scripts. QHC: the scheme (2020) does not mention the Queensland Housing Code; no QHC adoption found (text search for "Housing Code" returns nothing). Printed page numbers equal PDF page numbers.$q$);
