SELECT define_provision($q$BSC_PLANNING_SCHEME_2020@2020-02-07$q$, $q$QDC relationship: 1.6(1)$q$, 'APPLICATION', $q$Section 17(b) of the Regulation identifies the assessment benchmarks for building work that a local planning instrument must not change the effect to the extent the building work is regulated under the building assessment provisions, unless permitted under the Building Act 1975.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://burkeshire.prelive.opencities.com/files/assets/public/v/1/our-council/documents/planning-and-development/burke_shire_planning_scheme_2020.pdf$q$, NULL, NULL);
SELECT define_provision($q$BSC_PLANNING_SCHEME_2020@2020-02-07$q$, $q$QDC relationship: 1.6(3)$q$, 'APPLICATION', $q$This planning scheme, through Part 5, regulates building work in accordance with Sections 32 and 33 of the Building Act 1975.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://burkeshire.prelive.opencities.com/files/assets/public/v/1/our-council/documents/planning-and-development/burke_shire_planning_scheme_2020.pdf$q$, NULL, NULL);
SELECT define_provision($q$BSC_PLANNING_SCHEME_2020@2020-02-07$q$, $q$QDC relationship: 1.6 Editor’s note$q$, 'APPLICATION', $q$Editor’s note—the Building Act 1975 permits planning schemes to: • regulate, for the Building Code of Australia (BCA) or the Queensland Development Code (QDC), matters prescribed under a regulation under the Building Act 1975 (section 32). For example, building height and space for on-site parking. It may also regulate other matters such as designating floor levels of habitable rooms in flood areas, designating areas as being subject to bushfire hazard, noise corridors and end-of-trip facilities; • deal with an aspect of, or matter related or incidental to building work prescribed under a regulation under Section 32 of the Building Act 1975; • specify alternative design solutions for boundary clearance and site cover provisions for Class 1 and 10 structures under Section 33 of the Building Act 1975.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://burkeshire.prelive.opencities.com/files/assets/public/v/1/our-council/documents/planning-and-development/burke_shire_planning_scheme_2020.pdf$q$, NULL, NULL);
SELECT define_provision($q$BSC_PLANNING_SCHEME_2020@2020-02-07$q$, $q$QDC relationship: 5.8$q$, 'APPLICATION', $q$The following table identifies the categories of development and assessment for building work regulated under the planning scheme. || Zone | Categories of development and assessment | Assessment benchmarks for assessable development and requirements for accepted development || All | Code Assessment If development is on or located within 50m of a place or item identified in Schedule 5 – Local heritage register. | Table 7.2.1.3 of the General development code || | If development involves permanent or temporary physical obstructions or emissions intruding into the airport’s operational airspace areas identified on maps BTN AF1 and BTN AF2 within Schedule 2. | Table 7.2.1.3 of the General development code || Accepted development | Any building work listed in this table and not meeting the description listed in the “Categories of development and assessment” column.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://burkeshire.prelive.opencities.com/files/assets/public/v/1/our-council/documents/planning-and-development/burke_shire_planning_scheme_2020.pdf$q$, NULL, NULL);
SELECT define_provision($q$BSC_PLANNING_SCHEME_2020@2020-02-07$q$, $q$def Dwelling house$q$, 'DEFINITION', $q$A residential use of premises for one household that contains a single dwelling. The use includes domestic outbuildings and works normally associated with a dwelling and may include a secondary dwelling.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.1$q$, NULL, $q$https://burkeshire.prelive.opencities.com/files/assets/public/v/1/our-council/documents/planning-and-development/burke_shire_planning_scheme_2020.pdf$q$, NULL, NULL);
SELECT define_provision($q$BSC_PLANNING_SCHEME_2020@2020-02-07$q$, $q$def Domestic outbuilding$q$, 'DEFINITION', $q$A Class 10a building, as defined in the Building Code of Australia, that is ancillary to a residential use on the same premises and is limited to non-habitable buildings for the purpose of a shed, garage and carport.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.3$q$, NULL, $q$https://burkeshire.prelive.opencities.com/files/assets/public/v/1/our-council/documents/planning-and-development/burke_shire_planning_scheme_2020.pdf$q$, NULL, NULL);
SELECT define_provision($q$BSC_PLANNING_SCHEME_2020@2020-02-07$q$, $q$def Dwelling$q$, 'DEFINITION', $q$A building or part of a building used or capable of being used as a self-contained residence that must include the following: (a) food preparation facilities (b) a bath or shower (c) a toilet and wash basin (d) clothes washing facilities. This term includes outbuildings, structures and works normally associated with a dwelling.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.3$q$, NULL, $q$https://burkeshire.prelive.opencities.com/files/assets/public/v/1/our-council/documents/planning-and-development/burke_shire_planning_scheme_2020.pdf$q$, NULL, NULL);
SELECT define_provision($q$BSC_PLANNING_SCHEME_2020@2020-02-07$q$, $q$def Setback$q$, 'DEFINITION', $q$For a building or structure, the shortest distance measured horizontally from the outer most projection of a building or structure to the vertical projection of the boundary of the lot.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.3$q$, NULL, $q$https://burkeshire.prelive.opencities.com/files/assets/public/v/1/our-council/documents/planning-and-development/burke_shire_planning_scheme_2020.pdf$q$, NULL, NULL);
SELECT define_provision($q$BSC_PLANNING_SCHEME_2020@2020-02-07$q$, $q$LOA Table 5.5.1 Dwelling house / Township zone$q$, 'LEVEL_OF_ASSESSMENT', $q$Dwelling house | Accepted development subject to requirements | If located in the Residential precinct | General development code || Code assessment | Otherwise | Township zone code General development code$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://burkeshire.prelive.opencities.com/files/assets/public/v/1/our-council/documents/planning-and-development/burke_shire_planning_scheme_2020.pdf$q$, $q$Level: Accepted development subject to requirements (Residential precinct); Code assessment otherwise. Conditions: Residential precinct: AD subject to requirements against General development code; Commercial/Industrial precincts: code assessable against Township zone code and General development code$q$, NULL);
SELECT define_provision($q$BSC_PLANNING_SCHEME_2020@2020-02-07$q$, $q$LOA Table 5.5.3 Dwelling house / Rural residential zone$q$, 'LEVEL_OF_ASSESSMENT', $q$Dwelling house | Accepted development subject to requirements | General development code || Code assessment | Otherwise | Rural residential zone code General development code$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://burkeshire.prelive.opencities.com/files/assets/public/v/1/our-council/documents/planning-and-development/burke_shire_planning_scheme_2020.pdf$q$, $q$Level: Accepted development subject to requirements; Code assessment otherwise. Conditions: AD subject to requirements against General development code; otherwise code assessable$q$, NULL);
SELECT define_provision($q$BSC_PLANNING_SCHEME_2020@2020-02-07$q$, $q$LOA Table 5.5.4 Dwelling house / Rural zone$q$, 'LEVEL_OF_ASSESSMENT', $q$Caretaker’s accommodation Dwelling house | Accepted development subject to requirements | If: a) no more than two (2) dwellings for long term accommodation on a lot; b) not located in a bushfire prone area on SPP mapping – Natural hazards risk and resilience; and c) not located in an area where there is an identified abandoned mine. | General development code || Code assessment | Otherwise | Rural zone code General development code$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://burkeshire.prelive.opencities.com/files/assets/public/v/1/our-council/documents/planning-and-development/burke_shire_planning_scheme_2020.pdf$q$, $q$Level: Accepted development subject to requirements; Code assessment otherwise. Conditions: no more than two dwellings for long term accommodation; not bushfire prone; not in an identified abandoned mine area$q$, NULL);
SELECT define_provision($q$BSC_PLANNING_SCHEME_2020@2020-02-07$q$, $q$LOA Table 5.5.2 Dwelling house / Recreation and open space zone$q$, 'LEVEL_OF_ASSESSMENT', $q$Impact assessment | Any other use not listed in this table | The planning scheme$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://burkeshire.prelive.opencities.com/files/assets/public/v/1/our-council/documents/planning-and-development/burke_shire_planning_scheme_2020.pdf$q$, $q$Level: Impact assessment (not listed). Conditions: Dwelling house is not listed in Table 5.5.2$q$, NULL);
SELECT define_provision($q$BSC_PLANNING_SCHEME_2020@2020-02-07$q$, $q$LOA Table 5.8 Class 10 building work / All zones$q$, 'LEVEL_OF_ASSESSMENT', $q$Accepted development | Any building work listed in this table and not meeting the description listed in the “Categories of development and assessment” column.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://burkeshire.prelive.opencities.com/files/assets/public/v/1/our-council/documents/planning-and-development/burke_shire_planning_scheme_2020.pdf$q$, $q$Level: Accepted development (Code assessment only for local heritage / airport operational airspace). Conditions: Code assessable only if on or within 50m of a Schedule 5 local heritage place, or intruding into airport operational airspace (maps BTN AF1/AF2)$q$, NULL);

SELECT define_provision($q$BSC_PLANNING_SCHEME_2020@2020-02-07$q$, $q$Table 7.2.1.1 (AO5 excludes Dwelling houses); Tables 5.5.1, 5.5.3, 5.5.4; Table 5.8$q$, 'OTHER', $q$(No front setback is stated for a Dwelling house or its domestic outbuildings where the dwelling house is accepted development subject to requirements (Township zone – Residential precinct, Rural residential zone, Rural zone) or where Class 10 building work is carried out without a material change of use; the only General development code setback provision (AO5 / Table 7.2.1.4) excludes Dwelling houses, and the Township zone code has no front setback for a dwelling house; the QDC applies.)$q$, 'UNVERIFIED', $q$Table 5.5.1 printed p.25 / PDF p.25; Table 5.5.3 p.31; Table 5.5.4 p.36; Table 5.8 p.38; Table 7.2.1.1 AO5 p.56 (printed page = PDF page)$q$, NULL, $q$General development code / Township, Rural residential and Rural zone codes$q$, NULL, $q$https://burkeshire.prelive.opencities.com/files/assets/public/v/1/our-council/documents/planning-and-development/burke_shire_planning_scheme_2020.pdf$q$, $q$$q$, $q$bsc_dwelling_house_no_front_setback$q$);
SELECT define_rule($q${"rule_id": "BSC.bsc_dwelling_house_no_front_setback", "instrument_version": "BSC_PLANNING_SCHEME_2020@2020-02-07", "topic": "SETBACK.FRONTAGE", "title": "Table 7.2.1.1 (AO5 excludes Dwelling houses); Tables 5.5.1, 5.5.3, 5.5.4; Table 5.8", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "OTHER", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "(No front setback is stated for a Dwelling house or its domestic outbuildings where the dwelling house is accepted development subject to requirements (Township zone – Residential precinct, Rural residential zone, Rural zone) or where Class 10 building work is carried out without a material change of use; the only General development code setback provision (AO5 / Table 7.2.1.4) excludes Dwelling houses, and the Township zone code has no front setback for a dwelling house; the QDC applies.)", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2020-02-07", "verification": "UNVERIFIED", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "BURKE"}, {"level": "PRECINCT", "precinct": "BSC:TOWNSHIP/RESIDENTIAL"}, {"level": "PRECINCT", "precinct": "BSC:TOWNSHIP/COMMERCIAL"}, {"level": "PRECINCT", "precinct": "BSC:TOWNSHIP/INDUSTRIAL"}, {"level": "ZONE", "zone": "BSC:RURAL_RESIDENTIAL"}, {"level": "ZONE", "zone": "BSC:RURAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "bsc_dwelling_house_no_front_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"front setback\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"dwelling house accepted development subject to requirements, or Class 10 building work on an existing dwelling house lot\"], \"exceptions\": [\"Rural residential and Rural zones: where the dwelling house is code assessable, zone code AO1 applies (see bsc_rr_ao1_front_setback, bsc_rural_ao1_front_setback)\"], \"formula_text\": null}\nStructure scope 'Dwelling house (use \"includes domestic outbuildings and works normally associated with a dwelling\")' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: NO - no council provision; QDC MP1.1/MP1.2 boundary clearances apply\nResearcher notes: Dwelling house is accepted development subject to requirements against the General development code only (Township Residential precinct; Rural residential; Rural if <=2 dwellings, not bushfire prone, no abandoned mine). The only GDC part for accepted development subject to requirements is PO1/AO1 (flood). Township Commercial and Industrial precincts: dwelling house is code assessable against Township zone code + GDC, neither of which states a front setback for a dwelling house. Table 5.8: building work (e.g. a shed added later) is accepted development except for local heritage places and airport operational airspace, so no council setback applies to Class 10 building work."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$BSC.bsc_dwelling_house_no_front_setback@2020-02-07$q$;
SELECT define_provision($q$BSC_PLANNING_SCHEME_2020@2020-02-07$q$, $q$Table 7.2.1.1 (AO5 excludes Dwelling houses); Tables 5.5.1, 5.5.3, 5.5.4; Table 5.8$q$, 'OTHER', $q$(No side or rear setback is stated for a Dwelling house or its domestic outbuildings where the dwelling house is accepted development subject to requirements (Township zone – Residential precinct, Rural residential zone, Rural zone) or where Class 10 building work is carried out without a material change of use; the only General development code setback provision (AO5 / Table 7.2.1.4) excludes Dwelling houses, and the Township zone code has no side or rear setback for a dwelling house (other than Commercial precinct AO12.1); the QDC applies.)$q$, 'UNVERIFIED', $q$Table 5.5.1 p.25; Table 5.5.3 p.31; Table 5.5.4 p.36; Table 5.8 p.38; Table 7.2.1.1 AO5 p.56 (printed page = PDF page)$q$, NULL, $q$General development code / Township, Rural residential and Rural zone codes$q$, NULL, $q$https://burkeshire.prelive.opencities.com/files/assets/public/v/1/our-council/documents/planning-and-development/burke_shire_planning_scheme_2020.pdf$q$, $q$$q$, $q$bsc_dwelling_house_no_side_rear_setback$q$);
SELECT define_rule($q${"rule_id": "BSC.bsc_dwelling_house_no_side_rear_setback", "instrument_version": "BSC_PLANNING_SCHEME_2020@2020-02-07", "topic": "SETBACK.SIDE", "title": "Table 7.2.1.1 (AO5 excludes Dwelling houses); Tables 5.5.1, 5.5.3, 5.5.4; Table 5.8", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "OTHER", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": {"op": "unencoded", "text": "(No side or rear setback is stated for a Dwelling house or its domestic outbuildings where the dwelling house is accepted development subject to requirements (Township zone – Residential precinct, Rural residential zone, Rural zone) or where Class 10 building work is carried out without a material change of use; the only General development code setback provision (AO5 / Table 7.2.1.4) excludes Dwelling houses, and the Township zone code has no side or rear setback for a dwelling house (other than Commercial precinct AO12.1); the QDC applies.)", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2020-02-07", "verification": "UNVERIFIED", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "BURKE"}, {"level": "PRECINCT", "precinct": "BSC:TOWNSHIP/RESIDENTIAL"}, {"level": "PRECINCT", "precinct": "BSC:TOWNSHIP/COMMERCIAL"}, {"level": "PRECINCT", "precinct": "BSC:TOWNSHIP/INDUSTRIAL"}, {"level": "ZONE", "zone": "BSC:RURAL_RESIDENTIAL"}, {"level": "ZONE", "zone": "BSC:RURAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "bsc_dwelling_house_no_side_rear_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"side and rear setback\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"applies to side AND rear boundaries\", \"dwelling house accepted development subject to requirements, or Class 10 building work on an existing dwelling house lot\"], \"exceptions\": [\"Rural residential and Rural zones: where the dwelling house is code assessable, zone code AO1 applies\", \"Township Commercial precinct (code assessable): AO12.1 2m from a boundary shared with a residential precinct\"], \"formula_text\": null}\nStructure scope 'Dwelling house (use \"includes domestic outbuildings and works normally associated with a dwelling\")' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: NO - no council provision; QDC MP1.1/MP1.2 boundary clearances apply\nResearcher notes: See bsc_dwelling_house_no_front_setback. Township zone code AO17.1 (6m front / 2m from residential precinct boundary) applies only to a non-residential use in the residential precinct or adjoining a residential use, so it is not recorded for dwelling houses."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$BSC.bsc_dwelling_house_no_side_rear_setback@2020-02-07$q$;
SELECT define_provision($q$BSC_PLANNING_SCHEME_2020@2020-02-07$q$, $q$Table 6.2.3.2 PO1/AO1$q$, 'ACCEPTABLE_OUTCOME', $q$PO1 New development is located to contribute to the rural residential amenity and character of the area. | AO1 Buildings and structures are setback 20m from a State-controlled road otherwise 6m from all boundaries.$q$, 'VERIFIED_VERBATIM', $q$s6.2.3.2 printed p.48 / PDF p.48$q$, NULL, $q$Rural residential zone code$q$, NULL, $q$https://burkeshire.prelive.opencities.com/files/assets/public/v/1/our-council/documents/planning-and-development/burke_shire_planning_scheme_2020.pdf$q$, $q$Setback (SC1.3): "For a building or structure, the shortest distance measured horizontally from the outer most projection of a building or structure to the vertical projection of the boundary of the lot."$q$, $q$bsc_rr_ao1_front_setback$q$);
SELECT define_rule($q${"rule_id": "BSC.bsc_rr_ao1_front_setback", "instrument_version": "BSC_PLANNING_SCHEME_2020@2020-02-07", "topic": "SETBACK.FRONTAGE", "title": "Table 6.2.3.2 PO1/AO1", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "setback >= 20 if boundary is to a State-controlled road else >= 6", "extracted_value": 6, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2020-02-07", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "BURKE"}, {"level": "ZONE", "zone": "BSC:RURAL_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "bsc_rr_ao1_front_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"front setback\", \"operator\": \"conditional\", \"value\": 6, \"unit\": \"m\", \"conditions\": [\"20m from a State-controlled road\", \"otherwise 6m\"], \"exceptions\": [], \"formula_text\": \"setback >= 20 if boundary is to a State-controlled road else >= 6\"}\nStructure scope 'Buildings and structures' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: NO - not designated as a QDC alternative provision. Section 1.6(3) states only that \"This planning scheme, through Part 5, regulates building work in accordance with Sections 32 and 33 of the Building Act 1975\"; Table 5.8 (building work) makes building work code assessable only for local heritage places and airport operational airspace (benchmark Table 7.2.1.3). This AO applies to code assessable material change of use, not to building work.\nResearcher notes: Zone code applies only to assessable development: a Dwelling house in this zone is accepted development subject to requirements (General development code only); it becomes code assessable (\"Otherwise\") and then this code applies. \"Buildings and structures\" reaches Class 10 (domestic outbuildings form part of the Dwelling house use). Single provision covers front, side and rear. Zone codes prevail over use codes (s1.5(c))."}$q$::jsonb);
